  `lng` varchar(20) DEFAULT NULL COMMENT '경도',
  `lat` varchar(20) DEFAULT NULL COMMENT '위도',
  `etc` varchar(4000) DEFAULT NULL COMMENT '참고사항',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14204 DEFAULT CHARSET=utf8mb3;

